import { relations, sql } from 'drizzle-orm';
import {
	boolean,
	check,
	date,
	foreignKey,
	index,
	integer,
	jsonb,
	pgEnum,
	pgTable,
	text,
	timestamp,
	unique,
	uniqueIndex,
	uuid,
	varchar,
} from 'drizzle-orm/pg-core';
import {
	AI_PROVIDERS,
	ANSWER_CONTEXTS,
	COURSE_COLORS,
	COURSE_GOALS,
	EDUCATION_LEVELS,
	EXPLANATION_STYLES,
	PROFILE_USES,
	QUESTION_SOURCES,
	QUESTION_STATUSES,
	QUESTION_TYPES,
	STUDY_TIMES,
	TUTOR_ACTIONS,
} from '@orbi/shared';
import { user } from './auth';

// Orbi's own tables. The login tables in auth.ts are generated by Better Auth.

const timestamps = {
	createdAt: timestamp('created_at', { withTimezone: true })
		.defaultNow()
		.notNull(),
	updatedAt: timestamp('updated_at', { withTimezone: true })
		.defaultNow()
		.$onUpdate(() => new Date())
		.notNull(),
};

export const educationLevel = pgEnum('education_level', EDUCATION_LEVELS);

export const profileUse = pgEnum('profile_use', PROFILE_USES);

export const explanationStyle = pgEnum('explanation_style', EXPLANATION_STYLES);

export const studyTime = pgEnum('study_time', STUDY_TIMES);

export const courseColor = pgEnum('course_color', COURSE_COLORS);

// why the student takes the course; the AI tutor can plan around it later
export const courseGoal = pgEnum('course_goal', COURSE_GOALS);

// One row per user, so user_id is the primary key.
export const profile = pgTable('profile', {
	userId: text('user_id')
		.primaryKey()
		.references(() => user.id, { onDelete: 'cascade' }),
	preferredName: varchar('preferred_name', { length: 50 }),
	birthDate: date('birth_date'),
	educationLevel: educationLevel('education_level'),
	institution: text('institution'),
	fieldOfStudy: text('field_of_study'),
	occupation: text('occupation'),
	locale: text('locale'),
	interests: text('interests')
		.array()
		.notNull()
		.default(sql`'{}'::text[]`),
	// IANA name, for example "Europe/Istanbul"
	timezone: text('timezone'),
	uses: profileUse('uses')
		.array()
		.notNull()
		.default(sql`'{}'::profile_use[]`),
	explanationStyle: explanationStyle('explanation_style'),
	dailyMinutes: integer('daily_minutes'),
	studyTime: studyTime('study_time'),
	// set once every onboarding question is answered; the app stays closed until then
	onboardedAt: timestamp('onboarded_at', { withTimezone: true }),
	...timestamps,
});

export const course = pgTable(
	'course',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		userId: text('user_id')
			.notNull()
			.references(() => user.id, { onDelete: 'cascade' }),
		name: varchar('name', { length: 255 }).notNull(),
		description: text('description'),
		color: courseColor('color').notNull().default('blue'),
		goal: courseGoal('goal').notNull().default('keep_up'),
		examDate: date('exam_date'),
		...timestamps,
	},
	// also the index for "courses of a user"
	(t) => [unique('course_user_id_id_key').on(t.userId, t.id)]
);

// topic and note keep user_id for simple ownership checks. The foreign keys
// include user_id, so it always matches the owner of the course.
export const topic = pgTable(
	'topic',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		userId: text('user_id').notNull(),
		courseId: uuid('course_id').notNull(),
		name: varchar('name', { length: 255 }).notNull(),
		position: integer('position').notNull().default(0),
		...timestamps,
	},
	(t) => [
		foreignKey({
			name: 'topic_course_fk',
			columns: [t.userId, t.courseId],
			foreignColumns: [course.userId, course.id],
		}).onDelete('cascade'),
		unique('topic_user_id_id_key').on(t.userId, t.id),
		index('topic_course_id_idx').on(t.courseId, t.position),
	]
);

export const note = pgTable(
	'note',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		userId: text('user_id').notNull(),
		topicId: uuid('topic_id').notNull(),
		title: varchar('title', { length: 255 }).notNull(),
		content: text('content').notNull(),
		...timestamps,
	},
	(t) => [
		foreignKey({
			name: 'note_topic_fk',
			columns: [t.userId, t.topicId],
			foreignColumns: [topic.userId, topic.id],
		}).onDelete('cascade'),
		index('note_topic_id_idx').on(t.topicId),
		index('note_user_id_idx').on(t.userId),
		// at least one character that is not a space or a line break
		check('note_content_not_empty', sql`${t.content} ~ '\\S'`),
	]
);

export const tutorAction = pgEnum('tutor_action', TUTOR_ACTIONS);

export const chatRole = pgEnum('chat_role', ['user', 'assistant']);

export const aiProvider = pgEnum('ai_provider', AI_PROVIDERS);

export const questionType = pgEnum('question_type', QUESTION_TYPES);

export const questionStatus = pgEnum('question_status', QUESTION_STATUSES);

export const questionSource = pgEnum('question_source', QUESTION_SOURCES);

export const answerContext = pgEnum('answer_context', ANSWER_CONTEXTS);

// A tutor chat belongs to one topic, or to the whole course when topic_id is null.
// The id comes from the browser, so a new chat needs no extra request.
export const chat = pgTable(
	'chat',
	{
		id: uuid('id').primaryKey(),
		userId: text('user_id').notNull(),
		courseId: uuid('course_id').notNull(),
		topicId: uuid('topic_id'),
		title: varchar('title', { length: 255 }).notNull(),
		...timestamps,
	},
	(t) => [
		foreignKey({
			name: 'chat_course_fk',
			columns: [t.userId, t.courseId],
			foreignColumns: [course.userId, course.id],
		}).onDelete('cascade'),
		// a topic's chats go with the topic
		foreignKey({
			name: 'chat_topic_fk',
			columns: [t.userId, t.topicId],
			foreignColumns: [topic.userId, topic.id],
		}).onDelete('cascade'),
		unique('chat_user_id_id_key').on(t.userId, t.id),
		index('chat_course_id_idx').on(t.courseId, t.updatedAt),
	]
);

// parts are the AI SDK's UIMessage parts: text, reasoning, and tool calls with their data
export const chatMessage = pgTable(
	'chat_message',
	{
		id: uuid('id').primaryKey(),
		userId: text('user_id').notNull(),
		chatId: uuid('chat_id').notNull(),
		role: chatRole('role').notNull(),
		parts: jsonb('parts').$type<Record<string, unknown>[]>().notNull(),
		// a deleted topic keeps the history, just without the link
		topicId: uuid('topic_id').references(() => topic.id, {
			onDelete: 'set null',
		}),
		action: tutorAction('action'),
		// the catalog id, for assistant messages
		modelId: varchar('model_id', { length: 100 }),
		notesUsed: integer('notes_used'),
		...timestamps,
	},
	(t) => [
		foreignKey({
			name: 'chat_message_chat_fk',
			columns: [t.userId, t.chatId],
			foreignColumns: [chat.userId, chat.id],
		}).onDelete('cascade'),
		index('chat_message_chat_id_idx').on(t.chatId, t.createdAt),
	]
);

export const question = pgTable(
	'question',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		userId: text('user_id').notNull(),
		topicId: uuid('topic_id').notNull(),
		type: questionType('type').notNull().default('multiple_choice'),
		text: text('text').notNull(),
		choices: jsonb('choices').$type<string[]>().notNull(),
		correctChoice: integer('correct_choice').notNull(),
		explanation: text('explanation'),
		status: questionStatus('status').notNull().default('pending'),
		source: questionSource('source').notNull(),
		aiProvider: aiProvider('ai_provider'),
		aiModel: varchar('ai_model', { length: 100 }),
		// the reply that made it; no foreign key, because the question is saved while
		// that reply is still streaming, and deleting a chat should keep its questions
		chatMessageId: uuid('chat_message_id'),
		// its place in the set it was made in; a set is saved at once, so the time
		// alone cannot keep the order
		position: integer('position').notNull().default(0),
		...timestamps,
	},
	(t) => [
		foreignKey({
			name: 'question_topic_fk',
			columns: [t.userId, t.topicId],
			foreignColumns: [topic.userId, topic.id],
		}).onDelete('cascade'),
		unique('question_user_id_id_key').on(t.userId, t.id),
		index('question_topic_id_idx').on(t.topicId, t.status),
		index('question_user_id_idx').on(t.userId),
		check('question_text_not_empty', sql`${t.text} ~ '\\S'`),
		check(
			'question_correct_choice_in_range',
			sql`${t.correctChoice} >= 0 and ${t.correctChoice} < jsonb_array_length(${t.choices})`
		),
		// an AI question always says which model made it
		check(
			'question_ai_has_model',
			sql`${t.source} <> 'ai' or (${t.aiProvider} is not null and ${t.aiModel} is not null)`
		),
	]
);

// every answer the student gives; study sessions (US-06) add one each time they ask
export const answer = pgTable(
	'answer',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		userId: text('user_id').notNull(),
		questionId: uuid('question_id').notNull(),
		choice: integer('choice').notNull(),
		correct: boolean('correct').notNull(),
		context: answerContext('context').notNull(),
		answeredAt: timestamp('answered_at', { withTimezone: true })
			.defaultNow()
			.notNull(),
	},
	(t) => [
		foreignKey({
			name: 'answer_question_fk',
			columns: [t.userId, t.questionId],
			foreignColumns: [question.userId, question.id],
		}).onDelete('cascade'),
		// a question in the chat can be tried only once
		uniqueIndex('answer_chat_once_idx')
			.on(t.questionId)
			.where(sql`${t.context} = 'chat'`),
		index('answer_user_id_idx').on(t.userId, t.answeredAt),
	]
);

export const profileRelations = relations(profile, ({ one }) => ({
	user: one(user, { fields: [profile.userId], references: [user.id] }),
}));

export const courseRelations = relations(course, ({ one, many }) => ({
	user: one(user, { fields: [course.userId], references: [user.id] }),
	topics: many(topic),
}));

export const topicRelations = relations(topic, ({ one, many }) => ({
	course: one(course, { fields: [topic.courseId], references: [course.id] }),
	notes: many(note),
}));

export const noteRelations = relations(note, ({ one }) => ({
	topic: one(topic, { fields: [note.topicId], references: [topic.id] }),
}));

export const chatRelations = relations(chat, ({ one, many }) => ({
	course: one(course, { fields: [chat.courseId], references: [course.id] }),
	messages: many(chatMessage),
}));

export const chatMessageRelations = relations(chatMessage, ({ one }) => ({
	chat: one(chat, { fields: [chatMessage.chatId], references: [chat.id] }),
}));

export const questionRelations = relations(question, ({ one }) => ({
	topic: one(topic, { fields: [question.topicId], references: [topic.id] }),
}));
